"use client";
import {useState,useTransition} from "react";
import Link from "next/link";
import {useRouter} from "next/navigation";
import {assignBookingStaff,getStaffAssignmentOptions} from "@/app/actions/staff";
import {bookingDateLabel} from "@/lib/services/upcoming-bookings";
import type {AssignmentBooking} from "@/app/(dashboard)/dashboard/vendor/staff/StaffWorkspace";
import s from "@/components/vendor/business-workspace.module.css";
export default function AssignmentCard({booking,assignedName}:{booking:AssignmentBooking;assignedName?:string}){
 const router=useRouter(),[options,setOptions]=useState<Awaited<ReturnType<typeof getStaffAssignmentOptions>>|null>(null),[selected,setSelected]=useState(booking.staffMemberId??""),[pending,start]=useTransition(),[message,setMessage]=useState("");
 return <article className={s.divider}><div className={s.row}><div><Link className={s.heading} style={{fontSize:15}} href={`/dashboard/vendor/orders/service/booking/${booking.id}`}>{booking.product.name} ↗</Link><p className={s.muted}>{bookingDateLabel(booking.bookingDate)} · {booking.startTime}–{booking.endTime} · {booking.id.slice(-8).toUpperCase()}</p><span className={s.badge}>{assignedName??"Needs assignment"}</span></div><button className={s.secondary} disabled={pending} onClick={()=>start(async()=>{setMessage("");try{setOptions(await getStaffAssignmentOptions(booking.id));}catch(e){setMessage(e instanceof Error?e.message:"Could not check availability.");}})}>{pending?"Checking…":options?"Recheck availability":assignedName?"Review assignment":"Find available teammate"}</button></div>{options&&<form className={s.stack} style={{gap:12,marginTop:15}} onSubmit={e=>{e.preventDefault();start(async()=>{setMessage("");try{const result=await assignBookingStaff(booking.id,selected||null);if(result.error){setMessage(result.error);return;}setMessage("Assignment saved.");setOptions(null);router.refresh();}catch{setMessage("Could not save assignment.");}});}}><p className={s.small}>Available people are listed first, with the lightest appointment count for this day. Availability is checked again when you save.</p><select className={s.select} aria-label={`Team member for ${booking.product.name} ${booking.id.slice(-8)}`} value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Unassigned</option>{booking.staffMemberId&&!options.some(o=>o.id===booking.staffMemberId)&&<option value={booking.staffMemberId} disabled>{assignedName} · inactive</option>}{options.map(o=><option key={o.id} value={o.id} disabled={!!o.reason}>{o.name} · {o.reason??`${o.appointments} other appointments today`}</option>)}</select>{!options.some(o=>!o.reason)&&<p className={s.muted}>No available teammate fits this appointment. Review working hours, services or time off.</p>}<button className={s.button} disabled={pending||!!options.find(o=>o.id===selected)?.reason}>Save assignment</button></form>}{message&&<p role="status" className={s.muted} style={{marginTop:10}}>{message}</p>}</article>;
}
